-- KeySuite V4.28.54 — CR Price List from 010 - CR (Pricelist) - 261001 - V1.0.xlsx
alter table public.ks_app_settings add column if not exists cr_usd_multiplier numeric not null default 5.8;
alter table public.ks_app_settings add column if not exists cr_rmb_multiplier numeric not null default 0.65;

create table if not exists public.ks_products_cr (
  id text primary key,
  model text not null unique,
  source_row integer not null,
  source_workbook text not null,
  cr_usd numeric not null default 0, cr_rarity_usd text not null default 'common',
  crs_usd numeric not null default 0, crs_rarity_usd text not null default 'common',
  crn_usd numeric not null default 0, crn_rarity_usd text not null default 'common',
  cr_rmb numeric not null default 0, cr_rarity_rmb text not null default 'common',
  crs_rmb numeric not null default 0, crs_rarity_rmb text not null default 'common',
  crn_rmb numeric not null default 0, crn_rarity_rmb text not null default 'common',
  cr_myr numeric not null default 0, cr_rarity_myr text not null default 'common',
  crs_myr numeric not null default 0, crs_rarity_myr text not null default 'common',
  crn_myr numeric not null default 0, crn_rarity_myr text not null default 'common',
  updated_at timestamptz not null default now(),
  constraint ks_products_cr_rarity_ck check (
    cr_rarity_usd in ('common','many','rare','fixed') and crs_rarity_usd in ('common','many','rare','fixed') and crn_rarity_usd in ('common','many','rare','fixed') and
    cr_rarity_rmb in ('common','many','rare','fixed') and crs_rarity_rmb in ('common','many','rare','fixed') and crn_rarity_rmb in ('common','many','rare','fixed') and
    cr_rarity_myr in ('common','many','rare','fixed') and crs_rarity_myr in ('common','many','rare','fixed') and crn_rarity_myr in ('common','many','rare','fixed'))
);

on conflict (id) do update set model=excluded.model,source_row=excluded.source_row,source_workbook=excluded.source_workbook;

alter table public.ks_products_cr enable row level security;
drop policy if exists ks_products_cr_read on public.ks_products_cr;
create policy ks_products_cr_read on public.ks_products_cr for select to authenticated using (true);
revoke all on public.ks_products_cr from anon;
grant select on public.ks_products_cr to authenticated;

create or replace function public.keysuite_save_cr_product_price_v42854(
  p_product_id text,p_currency text,p_cr_price numeric,p_crs_price numeric,p_crn_price numeric,
  p_cr_rarity text,p_crs_rarity text,p_crn_rarity text)
returns public.ks_products_cr language plpgsql security definer set search_path=public as $$
declare v_email text:=lower(trim(coalesce(auth.jwt()->>'email','')));v_currency text:=upper(trim(coalesce(p_currency,'')));result public.ks_products_cr;
begin
  if not exists(select 1 from public.ks_user_access where lower(email)=v_email and active=true and lower(role)='owner') then raise exception 'Owner access required.'; end if;
  if v_currency not in ('USD','RMB','MYR') then raise exception 'Unsupported currency.'; end if;
  if lower(p_cr_rarity) not in ('common','many','rare','fixed') or lower(p_crs_rarity) not in ('common','many','rare','fixed') or lower(p_crn_rarity) not in ('common','many','rare','fixed') then raise exception 'Unsupported rarity value.'; end if;
  update public.ks_products_cr set
    cr_usd=case when v_currency='USD' then coalesce(p_cr_price,0) else cr_usd end,crs_usd=case when v_currency='USD' then coalesce(p_crs_price,0) else crs_usd end,crn_usd=case when v_currency='USD' then coalesce(p_crn_price,0) else crn_usd end,
    cr_rarity_usd=case when v_currency='USD' then lower(p_cr_rarity) else cr_rarity_usd end,crs_rarity_usd=case when v_currency='USD' then lower(p_crs_rarity) else crs_rarity_usd end,crn_rarity_usd=case when v_currency='USD' then lower(p_crn_rarity) else crn_rarity_usd end,
    cr_rmb=case when v_currency='RMB' then coalesce(p_cr_price,0) else cr_rmb end,crs_rmb=case when v_currency='RMB' then coalesce(p_crs_price,0) else crs_rmb end,crn_rmb=case when v_currency='RMB' then coalesce(p_crn_price,0) else crn_rmb end,
    cr_rarity_rmb=case when v_currency='RMB' then lower(p_cr_rarity) else cr_rarity_rmb end,crs_rarity_rmb=case when v_currency='RMB' then lower(p_crs_rarity) else crs_rarity_rmb end,crn_rarity_rmb=case when v_currency='RMB' then lower(p_crn_rarity) else crn_rarity_rmb end,
    cr_myr=case when v_currency='MYR' then coalesce(p_cr_price,0) else cr_myr end,crs_myr=case when v_currency='MYR' then coalesce(p_crs_price,0) else crs_myr end,crn_myr=case when v_currency='MYR' then coalesce(p_crn_price,0) else crn_myr end,
    cr_rarity_myr=case when v_currency='MYR' then lower(p_cr_rarity) else cr_rarity_myr end,crs_rarity_myr=case when v_currency='MYR' then lower(p_crs_rarity) else crs_rarity_myr end,crn_rarity_myr=case when v_currency='MYR' then lower(p_crn_rarity) else crn_rarity_myr end,updated_at=now()
  where id=p_product_id returning * into strict result;
  return result;
end $$;

create or replace function public.keysuite_save_cr_multiplier_v42854(p_currency text,p_multiplier numeric)
returns table(usd_multiplier numeric,rmb_multiplier numeric) language plpgsql security definer set search_path=public as $$
declare v_email text:=lower(trim(coalesce(auth.jwt()->>'email','')));v_currency text:=upper(trim(coalesce(p_currency,'')));
begin
  if not exists(select 1 from public.ks_user_access where lower(email)=v_email and active=true and lower(role)='owner') then raise exception 'Owner access required.'; end if;
  if v_currency not in ('USD','RMB') or coalesce(p_multiplier,0)<=0 then raise exception 'Invalid CR multiplier.'; end if;
  update public.ks_app_settings set cr_usd_multiplier=case when v_currency='USD' then p_multiplier else cr_usd_multiplier end,cr_rmb_multiplier=case when v_currency='RMB' then p_multiplier else cr_rmb_multiplier end where id='default';
  return query select cr_usd_multiplier,cr_rmb_multiplier from public.ks_app_settings where id='default';
end $$;

revoke all on function public.keysuite_save_cr_product_price_v42854(text,text,numeric,numeric,numeric,text,text,text) from public,anon;
grant execute on function public.keysuite_save_cr_product_price_v42854(text,text,numeric,numeric,numeric,text,text,text) to authenticated;
revoke all on function public.keysuite_save_cr_multiplier_v42854(text,numeric) from public,anon;
grant execute on function public.keysuite_save_cr_multiplier_v42854(text,numeric) to authenticated;
